import React, { useEffect, useState } from 'react';
import { generateKeys, encryptMessage, decryptMessage } from '../utils/crypto';

const Chat = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [ws, setWs] = useState(null);
  const [keys, setKeys] = useState({});

  useEffect(() => {
    const initChat = async () => {
      const socket = new WebSocket('ws://localhost:8080');
      setWs(socket);

      const { privateKey, publicKey } = await generateKeys();
      setKeys({ privateKey, publicKey });

      socket.onopen = () => {
        console.log('WebSocket connected');
      };

      socket.onmessage = async (event) => {
        const data = JSON.parse(event.data);

        if (data.type === 'key_exchange') {
          console.log('Received recipient public key');
          setKeys((prevKeys) => ({ ...prevKeys, recipientPublicKey: data.publicKey }));
        } else if (data.type === 'message') {
          // Передаём privateKey через замыкание
          const decryptedMessage = await decryptMessage(data.message, privateKey);
          setMessages((prev) => [...prev, { userId: data.userId, text: decryptedMessage }]);
        }
      };

      socket.onerror = (err) => {
        console.error('WebSocket error:', err);
      };

      socket.onclose = () => {
        console.log('WebSocket connection closed');
      };
    };

    initChat();
  }, []); // Зависимость пустая, потому что privateKey используется через замыкание

  const sendMessage = async (message, recipientPublicKey) => {
    try {
      if (!message) {
        alert('Message cannot be empty!');
        return;
      }

      if (!recipientPublicKey) {
        alert('Recipient public key is not yet available. Please wait.');
        console.error('Recipient public key is missing');
        return;
      }

      if (!ws || ws.readyState !== WebSocket.OPEN) {
        alert('WebSocket is not connected. Try refreshing the page.');
        console.error('WebSocket is not connected');
        return;
      }

      const encryptedMessage = await encryptMessage(message, recipientPublicKey);

      ws.send(JSON.stringify({ encryptedMessage }));
      setInput(''); // Очищаем поле ввода после отправки
    } catch (err) {
      console.error('Failed to send message:', err);
    }
  };

  return (
    <div>
      <h1>Anonymous Chat</h1>
      {!keys.recipientPublicKey && (
        <p style={{ color: 'red' }}>Waiting for recipient's public key...</p>
      )}
      <div>
        {messages.map((msg, index) => (
          <p key={index}>
            <strong>{msg.userId}:</strong> {msg.text}
          </p>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Type your message..."
      />
      <button
        onClick={() => sendMessage(input, keys.recipientPublicKey)}
        disabled={!keys.recipientPublicKey}
      >
        Send
      </button>
    </div>
  );
};

export default Chat;
